/** Reports the connection, the room, the people in it with their pointers, and whether a room is still loading. */
export namespace CollabStatus {
  /** An argument struct with no fields, for commands that take none. */
  export type Args = Record<string, never>;
  /** Where the connection to the server is. */
  type O_ConnectionState = "disconnected" | "ready" | "connecting" | "connected" | "error";
  /** A point of this user's own laser trail. */
  type O_LaserDot = {
    /** Milliseconds since the point was recorded. */
    age_ms: number;
    /** The point is gone when `age_ms` reaches this. */
    fade_ms: number;
    /** World x. */
    x: number;
    /** World y. */
    y: number;
    [key: string]: unknown;
  };
  /** Why the room is not usable yet. Present from the join until the first catch-up is applied. */
  type O_Loading = {
    phase: "connecting";
    [key: string]: unknown;
  } | {
    phase: "syncing";
    [key: string]: unknown;
  } | {
    /** Size of the update in bytes. */
    bytes: number;
    phase: "receiving";
    [key: string]: unknown;
  } | {
    /** Items (elements, files) shown so far. */
    done: number;
    phase: "importing";
    /** All items of the room. */
    total: number;
    [key: string]: unknown;
  };
  /** One other person in the room. */
  type O_PeerView = {
    /** `#rrggbb`. */
    color: string;
    /** True while this user follows the peer. */
    followed: boolean;
    /** The peer's id (32 hex characters). `collab.follow` takes it. */
    id: string;
    /** Display name, or a short form of the id. */
    name: string;
    /** Pointer in world coordinates; absent when it is outside the canvas. */
    pointer?: [number, number] | null;
    /** Ids of the elements the peer has selected. */
    selection: string[];
    /** The recent path of the pointer, oldest first. Drawn as a fading trail (the laser). */
    trail: O_TrailDot[];
    /** The peer's visible world rectangle `[x, y, w, h]`. */
    viewport?: [number, number, number, number] | null;
    [key: string]: unknown;
  };
  /** A point of a fading trail. */
  type O_TrailDot = {
    /** Milliseconds since the point was recorded. */
    age_ms: number;
    /** World x. */
    x: number;
    /** World y. */
    y: number;
    [key: string]: unknown;
  };
  /** Everything the UI shows about collaboration. */
  export type Output = {
    /** True when the command changed any state. */
    changed?: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** Why sharing stopped, in `Error` state. */
    error?: string | null;
    /** This user's laser trail. */
    laser: O_LaserDot[];
    /** Present while the room is not yet usable. */
    loading?: O_Loading | null;
    /** The other people in the room. */
    peers: O_PeerView[];
    /** The room this session is in. */
    room?: string | null;
    /** The connection. */
    state: O_ConnectionState;
    /** The tab bound to the room, as `tab.list` shows it (`t1`). */
    tab?: string | null;
    /** One sentence for a status bar. */
    text: string;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** True while local changes are not yet confirmed by the server. */
    unsynced: boolean;
    /** The server address, once one is chosen. */
    url?: string | null;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Builds a whole diagram from nodes and edges with symbolic ids: shapes with labels, bound arrows, one undo step. */
export namespace DiagramCreate {
  /** Which layout to run. */
  type A_Algorithm = "layered" | "tree" | "grid" | "force" | "none";
  /** Which ends of an edge have an arrowhead. */
  type A_Arrowheads = "none" | "end" | "start" | "both";
  /** The words `at` accepts. */
  type A_AtWord = "viewport_center" | "below_content";
  /** #rrggbb, or #rrggbbaa for a non-opaque colour. 'transparent' and #rgb are also accepted. */
  type A_Color = string;
  /** Where the diagram goes. */
  type A_DiagramAt = A_AtWord | [number, number];
  /** The direction layers grow in (layered and tree layouts). */
  type A_Direction = "down" | "right" | "up" | "left";
  /** One edge: an arrow from one node to another. */
  type A_EdgeSpec = {
    /** Straight (`sharp`), curved (`round`) or `elbow`. Default `sharp`. */
    arrow_type?: A_PathType | null;
    /** Which ends have a head. Default: at the target. */
    arrowheads?: A_Arrowheads | null;
    /** Marker at the target. Overrides `arrowheads`. */
    end_head?: A_Head | null;
    /** Symbolic id of the source node. */
    from: string;
    /** Text on the arrow. */
    label?: string | null;
    /** The element `name`. */
    name?: string | null;
    /** Marker at the source. Overrides `arrowheads`. */
    start_head?: A_Head | null;
    /** Style of the arrow. */
    style?: A_StyleSpec | null;
    /** Symbolic id of the target node. May equal `from` (a self loop). */
    to: string;
  };
  /** How a filled area is painted. The fill colour itself is `Style::fill_color`; `None` there means no fill. */
  type A_FillPattern = "solid" | "hachure" | "zigzag" | "cross_hatch" | "dots" | "dashed" | "zigzag_line";
  /**
   * Font family. `GelPen`, `GelPenSerif`, `VanillaExtract` and `PlexSans` ship with the app; `NotoSans` is the old
   * fallback.
   */
  type A_FontFamily = "gelpen" | "noto_sans" | "gelpen_serif" | "vanilla_extract" | "plex_sans";
  /** What is drawn at an end of a line or arrow. */
  type A_Head = "none" | "arrow" | "bar" | "circle" | "circle_outline" | "triangle" | "triangle_outline" | "diamond" | "diamond_outline" | "cardinality_one" | "cardinality_many" | "cardinality_one_or_many" | "cardinality_exactly_one" | "cardinality_zero_or_one" | "cardinality_zero_or_many";
  /** Layout options (`LayoutOpts` in the command catalog). */
  type A_LayoutOpts = {
    /** The algorithm. */
    algorithm?: A_Algorithm;
    /** Columns of the grid layout. Absent: about the square root of the node count. */
    columns?: number | null;
    /** Where layers grow (layered and tree). */
    direction?: A_Direction;
    /** Space between layers (between rows for grid). */
    layer_gap?: number;
    /** Space between neighbours in a layer (the other axis for grid). */
    node_gap?: number;
  };
  /** The shape of a node. */
  type A_NodeShape = "rectangle" | "ellipse" | "diamond" | "text";
  /** One node of the diagram. */
  type A_NodeSpec = {
    /** Height. Absent: measured from the label, at least 48. */
    height?: number | null;
    /** The symbolic id: a name the edges and groups use, unique in the diagram. The result maps it to the real id. */
    id: string;
    /** The text inside the node. Absent: an empty shape. */
    label?: string | null;
    /** The element `name`, so that later calls can say `@name`. */
    name?: string | null;
    /** The shape. */
    shape?: A_NodeShape;
    /** Width and height together. `width` and `height` win when both are given. */
    size?: [number, number] | null;
    /** Style. */
    style?: A_StyleSpec | null;
    /** Width. Absent: measured from the label, at least 80. */
    width?: number | null;
    /** Position for the `none` layout. */
    x?: number | null;
    /** Position for the `none` layout. */
    y?: number | null;
  };
  /** How the points of a line or arrow are joined. */
  type A_PathType = "sharp" | "round" | "elbow";
  /** How hand-drawn the outline looks. The names are the old app's; `roughness` gives the numeric value. */
  type A_Sloppiness = "architect" | "artist" | "cartoonist" | "drunk";
  /** Dash pattern of a stroke. */
  type A_StrokeStyle = "solid" | "dashed" | "dotted";
  /** The few style properties a node or an edge can set. Everything left out keeps the default. */
  type A_StyleSpec = {
    /** Corner radius. */
    corner_radius?: number | null;
    /** Fill colour. `"transparent"` means no fill. */
    fill_color?: A_Color | null;
    /** Fill pattern. */
    fill_pattern?: A_FillPattern | null;
    /** Font family of the label. */
    font_family?: A_FontFamily | null;
    /** Font size of the label. */
    font_size?: number | null;
    /** Opacity, 0 to 1. */
    opacity?: number | null;
    /** How hand-drawn the outline is. */
    sloppiness?: A_Sloppiness | null;
    /** Outline colour (text colour for a text node). */
    stroke_color?: A_Color | null;
    /** Dash pattern. */
    stroke_style?: A_StrokeStyle | null;
    /** Outline width. */
    stroke_width?: number | null;
  };
  /** Arguments of `diagram.create`. */
  export type Args = {
    /**
     * Where the diagram goes: a top-left point, `"viewport_center"` (default) or `"below_content"`. Ignored by the
     * `none` layout, which uses the `x` and `y` of the nodes.
     */
    at?: A_DiagramAt;
    /** The edges: one arrow per edge, bound to both nodes, with an optional label. */
    edges?: A_EdgeSpec[];
    /** Wrap the diagram in a frame with this name. */
    frame?: string | null;
    /** Put all nodes (and the arrows between them) in one group. */
    group?: boolean;
    /** How to place the nodes. Default: layered, top to bottom, gaps 40 and 80. */
    layout?: A_LayoutOpts;
    /** The nodes. `id` is a name you choose; edges refer to it, and the result maps it to the real element id. */
    nodes: A_NodeSpec[];
    /** Select the nodes and arrows afterwards. */
    select?: boolean;
  };
  /** A rectangle in command output. */
  type O_RectOut = {
    /** Height. */
    h: number;
    /** Width. */
    w: number;
    /** Left edge. */
    x: number;
    /** Top edge. */
    y: number;
    [key: string]: unknown;
  };
  /** The result of building a diagram. */
  export type Output = {
    /** Bounds of the whole diagram. */
    bounds: O_RectOut;
    /** True when the command changed any state. */
    changed?: boolean;
    /** Mermaid subgraphs: symbolic cluster id to the element id of its box. Edges may start or end at a box. */
    clusters: {
      [key: string]: string;
    };
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The arrows, in the order of `edges`. */
    edges: string[];
    /** The frame, when one was asked for. */
    frame?: string | null;
    /** The groups made, in order. */
    groups: string[];
    /** Symbolic node id to the real element id. In a batch, later steps use `$<step>.<node>`. */
    nodes: {
      [key: string]: string;
    };
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Adds a node of the same kind and style next to a shape, joined to it by a bound arrow, and selects it. */
