/** Writes the workspace (every tab) to storage now, if a document changed since the last write. */
export namespace DocAutosave {
  /** An argument struct with no fields, for commands that take none. */
  export type Args = Record<string, never>;
  /** What an autosave did. */
  export type Output = {
    /** False: the command wrote nothing the document or the session needed. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** True when a document was written because it had changed since the last autosave. */
    saved: boolean;
    /** Tabs in the workspace record. */
    tabs: number;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Deletes every element, locked ones included, and clears the selection. One undo step. */
export namespace DocClear {
  /** An argument struct with no fields, for commands that take none. */
  export type Args = Record<string, never>;
  /** What `doc.clear` removed. */
  export type Output = {
    /** True. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** Elements removed (bound text and frame children included). */
    removed: number;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Routes dropped files by content: images are inserted, documents opened, libraries imported. */
export namespace DocDrop {
  /** Where the middle of what is inserted goes. */
  type A_At = A_AtWord | [number, number];
  /** The words `at` accepts besides a point. */
  type A_AtWord = "viewport_center" | "$cursor";
  /** Bytes: inline as base64, or a path. */
  type A_Bytes = A_InlineBytes | A_PathBytes;
  /** Where a dropped document goes. */
  type A_DropDocs = "new_tab" | "replace" | "merge";
  /** One dropped file. */
  type A_DropItem = {
    /** The content: `{base64}` or `{path}`. */
    bytes: A_Bytes;
    /** The media type, if known. */
    mime?: string | null;
    /** The file name. */
    name: string;
  };
  /** Bytes given inline. */
  type A_InlineBytes = {
    /** The bytes as base64 (standard alphabet, padding optional). A `data:...;base64,` prefix is accepted. */
    base64: string;
    /** The media type the sender claims. It is not trusted: the content decides. */
    mime?: string | null;
    /** The file name, used in messages. */
    name?: string | null;
  };
  /** What to do with unsaved changes when a tab closes. */
  type A_OnUnsaved = "refuse" | "discard" | "save";
  /** Bytes read from a file through the `Files` port. */
  type A_PathBytes = {
    /** A path the session's file access can read. */
    path: string;
  };
  /** What to do with a PNG that carries a scene. */
  type A_ScenePng = "insert" | "open";
  /** Arguments of `doc.drop`. */
  export type Args = {
    /** World point to put images and merged elements at: a point, `viewport_center` (default) or `$cursor`. */
    at?: A_At;
    /** Documents: `new_tab` (default), `replace` or `merge`. */
    documents?: A_DropDocs;
    /** The dropped files (1 to 50). */
    items: A_DropItem[];
    /** What to do with unsaved changes when a document replaces the active one. */
    on_unsaved?: A_OnUnsaved;
    /** A PNG with an embedded scene: `insert` it as an image (default) or `open` the scene. */
    scene_png?: A_ScenePng;
  };
  /** What a drop did. */
  export type Output = {
    /** True when anything was opened, inserted or imported. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** Documents opened. */
    documents: number;
    /** Images inserted. */
    images: number;
    /** Library items added. */
    library_items: number;
    /** Files that were skipped (each is also a warning). */
    skipped: number;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Exports the selection or the whole document as PNG, SVG, JSON or .excalidraw, inline or to a file. */
export namespace DocExport {
  /** Where the export goes. */
  type A_Dest = A_InlineWord | A_FileRef;
  /** The export format. */
  type A_ExportFormat = "png" | "svg" | "json" | "excalidraw";
  /** What to export. */
  type A_ExportScope = "auto" | "all" | "selection" | "ids" | "frame";
  /** Where a file lives. */
  type A_FileRef = {
    /** The path. */
    path: string;
  } | {
    /** The name. */
    stored: string;
  } | {
    /** The file name. */
    download: string;
  } | {
    /** The handle id. */
    handle: string;
  };
  /** The only word `to` accepts besides a file. */
  type A_InlineWord = "inline";
  /** An element reference in arguments: an id, or `"@name"` for the name set with `element.set_name`. */
  type A_Ref = string;
  /** Arguments of `doc.export`. */
  export type Args = {
    /** Paint the document background. Default: the setting `export.background`. */
    background?: boolean | null;
    /** Draw with the dark palette (PNG and SVG). Default: the setting `export.dark`. */
    dark?: boolean | null;
    /** Embed the scene so that the picture can be opened again with `doc.open`. Default: the setting `export.embed_scene`. */
    embed_scene?: boolean | null;
    /** `png` (default), `svg`, `json` or `excalidraw`. */
    format?: A_ExportFormat;
    /** The frame, for scope `frame`. */
    frame?: A_Ref | null;
    /** The elements, for scope `ids`. */
    ids?: A_Ref[] | null;
    /** World units around the content, 0 to 1000. Default: the setting `export.padding`. */
    padding?: number | null;
    /** PNG and SVG size factor, 0.25 to 4. Default: the setting `export.scale`. */
    scale?: number | null;
    /** `auto` (default: the selection if there is one, else everything), `all`, `selection`, `ids` or `frame`. */
    scope?: A_ExportScope;
    /** `inline` (default) returns the bytes; a file is written through the files port. */
    to?: A_Dest;
  };
  /** The bytes of an inline export. */
  type O_ExportBytes = {
    /** The content, base64. */
    base64: string;
    /** Its media type. */
    mime: string;
    [key: string]: unknown;
  };
  /** The export format. */
  type O_ExportFormat = "png" | "svg" | "json" | "excalidraw";
  /** Where a file lives. */
  type O_FileRef = {
    /** The path. */
    path: string;
    [key: string]: unknown;
  } | {
    /** The name. */
    stored: string;
    [key: string]: unknown;
  } | {
    /** The file name. */
    download: string;
    [key: string]: unknown;
  } | {
    /** The handle id. */
    handle: string;
    [key: string]: unknown;
  };
  /** What an export produced. */
  export type Output = {
    /** The content, for `to: inline`. */
    bytes?: O_ExportBytes | null;
    /** Always false: an export changes no document. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** Elements exported. */
    elements: number;
    /** The format. */
    format: O_ExportFormat;
    /** Height in pixels (PNG). */
    height?: number | null;
    /** Its media type. */
    mime: string;
    /** Where it was written, for a file. */
    saved_to?: O_FileRef | null;
    /** Whether the scene is embedded in the picture (PNG, SVG). */
    scene_embedded: boolean;
    /** Size in bytes. */
    size: number;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    /** Width in pixels (PNG). */
    width?: number | null;
    [key: string]: unknown;
  };
}

/** Returns a summary of the document (counts, bounds, revision) or every field of its elements. */
