/** Returns the structure of the document in a compact, deterministic form: nodes, edges, groups and frames. */
export namespace DocOutline {
  /** What `doc.outline` returns. */
  type A_OutlineFormat = "text" | "json" | "both";
  /** Which part of the document the outline covers. */
  type A_OutlineScopeArg = "all" | "selection" | "visible" | "frame";
  /** An element reference in arguments: an id, or `"@name"` for the name set with `element.set_name`. */
  type A_Ref = string;
  /** Arguments of `doc.outline`. */
  export type Args = {
    /** `text`, `json` or `both`. */
    format?: A_OutlineFormat;
    /** With scope `frame`: the frame (an id or `@name`). */
    frame?: A_Ref | null;
    /** Show at most this many nodes and as many edges (1 to 5000). The text says when it cut something. */
    max_nodes?: number;
    /** `all`, `selection`, `visible` or `frame`. */
    scope?: A_OutlineScopeArg;
  };
  type O_ElementId = string;
  type O_GroupId = string;
  /** What is drawn at an end of a line or arrow. */
  type O_Head = "none" | "arrow" | "bar" | "circle" | "circle_outline" | "triangle" | "triangle_outline" | "diamond" | "diamond_outline" | "cardinality_one" | "cardinality_many" | "cardinality_one_or_many" | "cardinality_exactly_one" | "cardinality_zero_or_one" | "cardinality_zero_or_many";
  /** The kind tag without data. */
  type O_Kind = "rectangle" | "diamond" | "ellipse" | "line" | "arrow" | "freehand" | "text" | "math" | "image" | "frame";
  /** The structure of the document for an agent. */
  type O_Outline = {
    /** Arrows with their ends. */
    edges: O_OutlineEdge[];
    /** Frames. */
    frames: O_OutlineFrame[];
    /** Groups. */
    groups: O_OutlineGroup[];
    /** Shapes, images, math, lines and freehand strokes, in reading order. */
    nodes: O_OutlineNode[];
    /** Free text that no arrow connects and that labels nothing. */
    texts: O_OutlineNode[];
    /** Present when something was left out. */
    truncated?: O_Truncation | null;
    [key: string]: unknown;
  };
  /** An arrow. */
  type O_OutlineEdge = {
    /** Marker at the end. */
    end_head: O_Head;
    /** What the start is bound to. `None`: loose. */
    from?: O_ElementId | null;
    /** The arrow's id. */
    id: O_ElementId;
    /** The arrow's bound text. */
    label?: string | null;
    /** The `name`. */
    name?: string | null;
    /** Straight, curved or elbow. */
    path: O_PathType;
    /** Marker at the start. */
    start_head: O_Head;
    /** What the end is bound to. `None`: loose. */
    to?: O_ElementId | null;
    [key: string]: unknown;
  };
  /** A frame and what is in it. */
  type O_OutlineFrame = {
    /** `[x, y, w, h]`. */
    bounds: [number, number, number, number];
    /** Child ids: nodes and arrows, in outline order. */
    children: O_ElementId[];
    /** Element id. */
    id: O_ElementId;
    /** The title. */
    name?: string | null;
    [key: string]: unknown;
  };
  /** A group with at least two live members. */
  type O_OutlineGroup = {
    /** Group id. */
    id: O_GroupId;
    /** Member ids in outline order (labels follow their containers and are not listed). */
    members: O_ElementId[];
    [key: string]: unknown;
  };
  /** A shape, text or other thing in the outline. */
  type O_OutlineNode = {
    /** `[x, y, w, h]`, rounded to whole units. */
    bounds: [number, number, number, number];
    /** The frame it is in. */
    frame?: O_ElementId | null;
    /** Element id. */
    id: O_ElementId;
    /** The kind. */
    kind: O_Kind;
    /** The text inside (bound label, own text or LaTeX). */
    label?: string | null;
    /** Locked. */
    locked: boolean;
    /** The `name` an agent can address it by. */
    name?: string | null;
    [key: string]: unknown;
  };
  /** How the points of a line or arrow are joined. */
  type O_PathType = "sharp" | "round" | "elbow";
  /** Said when the outline is cut short. */
  type O_Truncation = {
    /** Edges shown. */
    edges_shown: number;
    /** Edges in scope. */
    edges_total: number;
    /** What to do about it. */
    hint: string;
    /** Nodes shown. */
    nodes_shown: number;
    /** Nodes in scope (shapes and loose texts). */
    nodes_total: number;
    [key: string]: unknown;
  };
  /** Output of `doc.outline`. */
  export type Output = {
    /** True when the command changed any state. */
    changed?: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** Nodes, edges, loose texts, groups and frames. Absent for format `text`. */
    outline?: O_Outline | null;
    /** One line per node and per edge, in a fixed order. Absent for format `json`. */
    text?: string | null;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

