/** Returns the newest entries of the recent-command ring, oldest first, with arguments, outcome and duration. */
export namespace EngineRecent {
  /** Arguments of `engine.recent`. */
  export type Args = {
    /** How many entries, 1 to 256. */
    limit?: number;
    /** Leave out read-only commands. */
    mutating_only?: boolean;
    /** Only entries after this sequence number. */
    since_seq?: number | null;
  };
  /** Who made the call. Recorded in the ring; never changes the result. */
  type O_Origin = "ui" | "shortcut" | "menu" | "context_menu" | "palette" | "script" | "agent" | "remote" | "test";
  /** What a call came to. */
  type O_Outcome = {
    /** Whether it changed any state. */
    changed: boolean;
    /** Always true. */
    ok: boolean;
    /** The undo label when it pushed a step. */
    undo_label?: string | null;
    [key: string]: unknown;
  } | {
    /** The refusal code. */
    code: string;
    /** The refusal text. */
    message: string;
    /** Always false. */
    ok: boolean;
    [key: string]: unknown;
  };
  /** One recorded call. */
  type O_RingEntry = {
    /** The arguments as JSON text, cut to 512 bytes. Image bytes are replaced by their length. */
    args: string;
    /** How long it took. */
    duration_us: number;
    /** For a gesture: the number of frames. */
    frames?: number | null;
    /** The command id (for a batch, `batch`). */
    id: string;
    /** False for read-only commands. */
    mutating: boolean;
    /** Success or refusal. */
    outcome: O_Outcome;
    /** Counts up from 1 over the life of the session. */
    seq: number;
    /** Who called. */
    source: O_Origin;
    /** For a batch: the number of steps. */
    steps?: number | null;
    /** Wall time in milliseconds since the Unix epoch. */
    t_ms: number;
    [key: string]: unknown;
  };
  /** Output of `engine.recent`. */
  export type Output = {
    /** The ring's capacity. */
    capacity: number;
    /** True when the command changed any state. */
    changed?: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The newest entries, oldest first. */
    entries: O_RingEntry[];
    /** The sequence number the next entry will get. */
    next_seq: number;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

