/** Inserts PNG, JPEG or WebP pictures as image elements, scaled to fit, stored once per content in the document. */
export namespace ImageInsert {
  /** Where the middle of what is inserted goes. */
  type A_At = A_AtWord | [number, number];
  /** The words `at` accepts besides a point. */
  type A_AtWord = "viewport_center" | "$cursor";
  /** Bytes: inline as base64, or a path. */
  type A_Bytes = A_InlineBytes | A_PathBytes;
  /** Bytes given inline. */
  type A_InlineBytes = {
    /** The bytes as base64 (standard alphabet, padding optional). A `data:...;base64,` prefix is accepted. */
    base64: string;
    /** The media type the sender claims. It is not trusted: the content decides. */
    mime?: string | null;
    /** The file name, used in messages. */
    name?: string | null;
  };
  /** Bytes read from a file through the `Files` port. */
  type A_PathBytes = {
    /** A path the session's file access can read. */
    path: string;
  };
  /** Arguments of `image.insert`. */
  export type Args = {
    /** Where the middle of the first picture goes, in world units. Default: the middle of the visible canvas. */
    at?: A_At;
    /** Store a picture over 2 MiB and 2048 px on the long side scaled down to 2048 px. */
    downscale?: boolean;
    /**
     * The longest side a picture is shown at. A larger picture is scaled down to this; a smaller one keeps its
     * size.
     */
    fit?: number;
    /** The pictures: 1 to 20, each `{base64, name?, mime?}` or `{path}`. PNG, JPEG or WebP, at most 25 MiB each. */
    images: A_Bytes[];
    /** A name for messages about pictures that carry no `name` of their own. */
    name?: string | null;
    /** Each further picture is moved by this many units right and down, so a batch does not stack. */
    offset?: number;
    /** Select the new elements. */
    select?: boolean;
  };
  /** One inserted picture. */
  type O_Inserted = {
    /** The content hash under which the bytes are stored in the document. */
    file_id: string;
    /** Height of the element in world units. */
    height: number;
    /** The element. */
    id: string;
    /** Height of the stored picture in pixels. */
    natural_height: number;
    /** Width of the stored picture in pixels. */
    natural_width: number;
    /** True when the document already held these bytes, so nothing new was stored. */
    reused: boolean;
    /** True when the picture was big and was stored smaller. */
    shrunk: boolean;
    /** Width of the element in world units. */
    width: number;
    [key: string]: unknown;
  };
  /** Output of `image.insert`. */
  export type Output = {
    /** True when the command changed any state. */
    changed?: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The new elements, in order. */
    ids: string[];
    /** One entry per picture. */
    images: O_Inserted[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Arranges the selected shapes with a layout algorithm and re-routes the arrows bound between them. */
export namespace LayoutApply {
  /** Where the laid-out set ends up. */
  type A_Anchor = "keep" | "top_left" | "center";
  /** #rrggbb, or #rrggbbaa for a non-opaque colour. 'transparent' and #rgb are also accepted. */
  type A_Color = string;
  /** Arrows bound to an element, and the elements on their other end. */
  type A_ConnectedTo = {
    /** The direction of the arrows. */
    direction?: A_LinkDirection;
    /** The element. */
    ref: A_ElementId;
  };
  /** The direction layers grow in (layered and tree layouts). */
  type A_Direction = "down" | "right" | "up" | "left";
  type A_ElementId = string;
  /** How a filled area is painted. The fill colour itself is `Style::fill_color`; `None` there means no fill. */
  type A_FillPattern = "solid" | "hachure" | "zigzag" | "cross_hatch" | "dots" | "dashed" | "zigzag_line";
  /**
   * Font family. `GelPen`, `GelPenSerif`, `VanillaExtract` and `PlexSans` ship with the app; `NotoSans` is the old
   * fallback.
   */
  type A_FontFamily = "gelpen" | "noto_sans" | "gelpen_serif" | "vanilla_extract" | "plex_sans";
  type A_GroupId = string;
  /** The kind tag without data. */
  type A_Kind = "rectangle" | "diamond" | "ellipse" | "line" | "arrow" | "freehand" | "text" | "math" | "image" | "frame";
  /** The algorithms `layout.apply` runs (`none` would keep everything where it is). */
  type A_LayoutAlgorithm = "layered" | "tree" | "grid" | "force";
  /** Which arrows count as a connection. */
  type A_LinkDirection = "in" | "out" | "any";
  /** One value or a list of values. */
  type A_OneOrMany = A_Kind | A_Kind[];
  /**
   * The filter of `element.query`. Every given field must match (AND).
   *
   * Labels that are bound to a shape follow their container: they are left out of the result unless the filter asks
   * for kind `text`, names `ids`, or sets `bound_text_of`.
   */
  type A_Query = {
    /** The label of this container. */
    bound_text_of?: A_ElementId | null;
    /** Connected by arrows to this element. */
    connected_to?: A_ConnectedTo | null;
    /** Children of this frame. */
    frame?: A_ElementId | null;
    /** Members of this group. */
    group?: A_GroupId | null;
    /** Has a bound label or not. */
    has_label?: boolean | null;
    /** Only these elements. */
    ids?: A_ElementId[] | null;
    /** One kind or a list of kinds. */
    kind?: A_OneOrMany | null;
    /** Locked or not. */
    locked?: boolean | null;
    /** The element name, as a glob (`*` any run, `?` one character). Case-sensitive. */
    name?: string | null;
    /** A region of the canvas. */
    region?: A_RegionFilter | null;
    /** In the selection or not. */
    selected?: boolean | null;
    /** Style values. */
    style?: A_StyleFilter | null;
    /** Text, labels and LaTeX that match. */
    text?: A_TextFilter | null;
  };
  /** A rectangle as `{x, y, w, h}`. */
  type A_RectSpec = {
    /** Height. */
    h: number;
    /** Width. */
    w: number;
    /** Left. */
    x: number;
    /** Top. */
    y: number;
  };
  /** An element reference in arguments: an id, or `"@name"` for the name set with `element.set_name`. */
  type A_Ref = string;
  /** Elements in a region of the canvas, by their (rotated) bounding boxes. */
  type A_RegionFilter = {
    /** How the element relates to it. */
    mode?: A_RegionMode;
    /** The region. */
    rect: A_RectSpec;
  };
  /** How an element relates to the region. */
  type A_RegionMode = "overlap" | "contain" | "contained_by";
  /** How hand-drawn the outline looks. The names are the old app's; `roughness` gives the numeric value. */
  type A_Sloppiness = "architect" | "artist" | "cartoonist" | "drunk";
  /** Dash pattern of a stroke. */
  type A_StrokeStyle = "solid" | "dashed" | "dotted";
  /** Exact style values to match. Only the properties that are given are compared. */
  type A_StyleFilter = {
    /** Corner radius. */
    corner_radius?: number | null;
    /** Fill colour. `"transparent"` matches elements without a fill. */
    fill_color?: A_Color | null;
    /** Fill pattern. */
    fill_pattern?: A_FillPattern | null;
    /** Font family (text only). */
    font_family?: A_FontFamily | null;
    /** Font size (text only). */
    font_size?: number | null;
    /** Opacity. */
    opacity?: number | null;
    /** Sloppiness. */
    sloppiness?: A_Sloppiness | null;
    /** Stroke colour. */
    stroke_color?: A_Color | null;
    /** Dash pattern. */
    stroke_style?: A_StrokeStyle | null;
    /** Stroke width. */
    stroke_width?: number | null;
    /** Text alignment (text only). */
    text_align?: A_TextAlign | null;
  };
  /** Horizontal text alignment. */
  type A_TextAlign = "left" | "center" | "right";
  /** Text to look for in the text of elements, their labels and LaTeX. Case-insensitive. */
  type A_TextFilter = string | {
    /** A phrase the text contains. */
    contains?: string | null;
    /** A regular expression: literals, `.`, classes like `[a-z]`, `* + ?`, `^ $`, `|`, and `\d \w \s`. */
    regex?: string | null;
  };
  /** Arguments of `layout.apply`. */
  export type Args = {
    /** The algorithm. */
    algorithm?: A_LayoutAlgorithm;
    /** Where the result sits. */
    anchor?: A_Anchor;
    /** With `anchor` = `top_left`: the world point `[x, y]` the top-left corner goes to. */
    at?: [number, number] | null;
    /** Columns of the grid layout. Absent: about the square root of the node count. */
    columns?: number | null;
    /** Where layers grow (layered and tree): `down`, `right`, `up` or `left`. */
    direction?: A_Direction;
    /** Select the shapes with a query instead of `ids` (see `element.query`). */
    filter?: A_Query | null;
    /** The shapes to lay out. Arrows between them are re-routed. Default: the selection. Give `ids` or `filter`. */
    ids?: A_Ref[] | null;
    /** Space between layers (between rows for grid). */
    layer_gap?: number;
    /** Space between neighbours in a layer. */
    node_gap?: number;
    /** Re-route the bound arrows after the move (elbow routes once, after all moves). */
    reroute?: boolean;
  };
  /** A rectangle in command output. */
  type O_RectOut = {
    /** Height. */
    h: number;
    /** Width. */
    w: number;
    /** Left edge. */
    x: number;
    /** Top edge. */
    y: number;
    [key: string]: unknown;
  };
  /** Output of `layout.apply`. */
  export type Output = {
    /** The bounds of the shapes after the layout. */
    bounds: O_RectOut;
    /** True when the command changed any state. */
    changed?: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The shapes that moved. */
    moved: string[];
    /** The arrows that were re-routed. */
    rerouted: string[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Stores a copy of the selected (or given) elements as a new library item. */
export namespace LibraryAdd {
  /** An element reference in arguments: an id, or `"@name"` for the name set with `element.set_name`. */
  type A_Ref = string;
  /** Arguments of `library.add`. */
  export type Args = {
    /** The elements. Default: the selection. */
    ids?: A_Ref[] | null;
    /** A name for the item (1 to 256 characters). */
    name?: string | null;
  };
  /** What `library.list` and `library.add` say about an item. */
  type O_ItemInfo = {
    /** Bounds `[x, y, w, h]` of the item (it starts at 0, 0). */
    bounds?: [number, number, number, number] | null;
    /**
     * A fingerprint of what the item draws (16 hex digits). It changes when the drawing does, and not when the
     * item is renamed, so a picture of the item stays good for as long as this stays the same.
     */
    content: string;
    /** When it was added, milliseconds since the Unix epoch. */
    created: number;
    /** Visible elements in the item. */
    element_count: number;
    /** The id to pass as `item`. */
    id: string;
    /** The name, if it has one. */
    name?: string | null;
    /** The section the item belongs to: `mine` for the person's own items, else the id of an imported library. */
    section: string;
    [key: string]: unknown;
  };
  /** Output of `library.add`. */
  export type Output = {
    /** True. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The new item. */
    item: O_ItemInfo;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Writes the library (or some items) as an .excalidrawlib v2 file, inline or to a file. */
export namespace LibraryExport {
  /** Where the export goes. */
  type A_Dest = A_InlineWord | A_FileRef;
  /** Where a file lives. */
  type A_FileRef = {
    /** The path. */
    path: string;
  } | {
    /** The name. */
    stored: string;
  } | {
    /** The file name. */
    download: string;
  } | {
    /** The handle id. */
    handle: string;
  };
  /** The only word `to` accepts besides a file. */
  type A_InlineWord = "inline";
  /** Arguments of `library.export`. */
  export type Args = {
    /** Item ids or names. Default: all items. */
    items?: string[] | null;
    /** `inline` (default) returns the bytes; a file is written through the files port. */
    to?: A_Dest;
  };
  /** The bytes of an inline export. */
  type O_ExportBytes = {
    /** The content, base64. */
    base64: string;
    /** Its media type. */
    mime: string;
    [key: string]: unknown;
  };
  /** Where a file lives. */
  type O_FileRef = {
    /** The path. */
    path: string;
    [key: string]: unknown;
  } | {
    /** The name. */
    stored: string;
    [key: string]: unknown;
  } | {
    /** The file name. */
    download: string;
    [key: string]: unknown;
  } | {
    /** The handle id. */
    handle: string;
    [key: string]: unknown;
  };
  /** Output of `library.export`. */
  export type Output = {
    /** The content, for `to: inline`. */
    bytes?: O_ExportBytes | null;
    /** Always false. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** Items written. */
    items: number;
    /** Where it was written, for a file. */
    saved_to?: O_FileRef | null;
    /** Size in bytes. */
    size: number;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Reads an .excalidrawlib file (v1 or v2) and merges it into the library, replaces the library, or opens it as a tab. */
export namespace LibraryImport {
  /** Where a file lives. */
  type A_FileRef = {
    /** The path. */
    path: string;
  } | {
    /** The name. */
    stored: string;
  } | {
    /** The file name. */
    download: string;
  } | {
    /** The handle id. */
    handle: string;
  };
  /** How an imported library meets the existing one. */
  type A_ImportMode = "merge" | "replace" | "open_as_tab";
  /** Bytes given inline. */
  type A_InlineBytes = {
    /** The bytes as base64 (standard alphabet, padding optional). A `data:...;base64,` prefix is accepted. */
    base64: string;
    /** The media type the sender claims. It is not trusted: the content decides. */
    mime?: string | null;
    /** The file name, used in messages. */
    name?: string | null;
  };
  /** Where the data of a command comes from: inline bytes, or a file or stored name that the session reads. */
  type A_Source = A_InlineBytes | A_FileRef;
  /** Arguments of `library.import`. */
  export type Args = {
    /** `merge` (default), `replace` or `open_as_tab`. */
    mode?: A_ImportMode;
    /** The `.excalidrawlib` file: `{path}`, `{stored}`, `{handle}` or `{base64, name?}`. */
    source: A_Source;
  };
  /** Output of `library.import`. */
  export type Output = {
    /** Items added to the library. */
    added: number;
    /** True when the library or the tabs changed. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The section the new items went to (named after the file), when there are any. */
    section?: string | null;
    /** Items skipped because the library already has them (or the file has them twice). */
    skipped: number;
    /** The new tab, for `open_as_tab`. */
    tab?: string | null;
    /** Items in the library now. */
    total: number;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Inserts a library item like a paste: new ids, centred on a point, selected. */
export namespace LibraryInsert {
  /** Arguments of `library.insert`. */
  export type Args = {
    /** The world point to centre the item on. Default: the centre of the viewport. */
    at?: [number, number] | null;
    /** The item id or name. */
    item: string;
    /** Select the inserted elements. Default true. */
    select?: boolean;
  };
  /** Output of `library.insert`. */
  export type Output = {
    /** True. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The new elements, back to front. */
    ids: string[];
    /** The item that was inserted. */
    item: string;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Lists the library items with id, section, name, element count, bounds and creation time, and the sections. */
export namespace LibraryList {
  /** Arguments of `library.list`. */
  export type Args = {
    /** Only items whose name or id contains this text (case does not matter). */
    search?: string | null;
    /** Only the items of this section (id or name). */
    section?: string | null;
  };
  /** What `library.list` and `library.add` say about an item. */
  type O_ItemInfo = {
    /** Bounds `[x, y, w, h]` of the item (it starts at 0, 0). */
    bounds?: [number, number, number, number] | null;
    /**
     * A fingerprint of what the item draws (16 hex digits). It changes when the drawing does, and not when the
     * item is renamed, so a picture of the item stays good for as long as this stays the same.
     */
    content: string;
    /** When it was added, milliseconds since the Unix epoch. */
    created: number;
    /** Visible elements in the item. */
    element_count: number;
    /** The id to pass as `item`. */
    id: string;
    /** The name, if it has one. */
    name?: string | null;
    /** The section the item belongs to: `mine` for the person's own items, else the id of an imported library. */
    section: string;
    [key: string]: unknown;
  };
  /** What `library.list` and `library.rename_section` say about a section. */
  type O_SectionInfo = {
    /** The id to pass as `section`, and the `section` of its items. */
    id: string;
    /** Items in it (all of them, whatever `search` says). */
    items: number;
    /** Whose items it holds. */
    kind: O_SectionKind;
    /** The name: the file an imported library came from, or `My items`. */
    name: string;
    [key: string]: unknown;
  };
  /** Whose items a section holds. */
  type O_SectionKind = "mine" | "imported";
  /** Output of `library.list`. */
  export type Output = {
    /** Always false. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The items, in library order. */
    items: O_ItemInfo[];
    /** The sections that have items, the person's own first. Every item's `section` is the id of one of them. */
    sections: O_SectionInfo[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Removes library items by id or name, or all of them with all=true. Not undoable. */
export namespace LibraryRemove {
  /** Arguments of `library.remove`. */
  export type Args = {
    /** Remove every item. The only way to empty the library. */
    all?: boolean;
    /** Item ids or names to remove. Give either this or `all`. */
    items?: string[] | null;
  };
  /** Output of `library.remove`. */
  export type Output = {
    /** False when there was nothing to remove. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The ids that were removed. */
    removed: string[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Removes a section of the library (an imported library, or your own items) with all its items. Not undoable. */
export namespace LibraryRemoveSection {
  /** Arguments of `library.remove_section`. */
  export type Args = {
    /** The section id or name (`mine` for the person's own items). */
    section: string;
  };
  /** Output of `library.remove_section`. */
  export type Output = {
    /** False when the section had no items. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The ids of the items that were removed with it. */
    removed: string[];
    /** The id of the section. */
    section: string;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Gives a library item a new name. */
export namespace LibraryRename {
  /** Arguments of `library.rename`. */
  export type Args = {
    /** The item id or name. */
    item: string;
    /** The new name (1 to 256 characters). */
    name: string;
  };
  /** What `library.list` and `library.add` say about an item. */
  type O_ItemInfo = {
    /** Bounds `[x, y, w, h]` of the item (it starts at 0, 0). */
    bounds?: [number, number, number, number] | null;
    /**
     * A fingerprint of what the item draws (16 hex digits). It changes when the drawing does, and not when the
     * item is renamed, so a picture of the item stays good for as long as this stays the same.
     */
    content: string;
    /** When it was added, milliseconds since the Unix epoch. */
    created: number;
    /** Visible elements in the item. */
    element_count: number;
    /** The id to pass as `item`. */
    id: string;
    /** The name, if it has one. */
    name?: string | null;
    /** The section the item belongs to: `mine` for the person's own items, else the id of an imported library. */
    section: string;
    [key: string]: unknown;
  };
  /** Output of `library.rename`. */
  export type Output = {
    /** False when the item already had this name. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The item after the command. */
    item: O_ItemInfo;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Gives an imported library's section a new name. Your own items keep the name My items. */
export namespace LibraryRenameSection {
  /** Arguments of `library.rename_section`. */
  export type Args = {
    /** The new name (1 to 256 characters). */
    name: string;
    /** The section id or name. */
    section: string;
  };
  /** What `library.list` and `library.rename_section` say about a section. */
  type O_SectionInfo = {
    /** The id to pass as `section`, and the `section` of its items. */
    id: string;
    /** Items in it (all of them, whatever `search` says). */
    items: number;
    /** Whose items it holds. */
    kind: O_SectionKind;
    /** The name: the file an imported library came from, or `My items`. */
    name: string;
    [key: string]: unknown;
  };
  /** Whose items a section holds. */
  type O_SectionKind = "mine" | "imported";
  /** Output of `library.rename_section`. */
  export type Output = {
    /** False when the section already had this name. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The section after the command. */
    section: O_SectionInfo;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Draws a library item as a small PNG with a transparent background, in the light or the dark palette. */
export namespace LibraryThumbnail {
  /** Arguments of `library.thumbnail`. */
  export type Args = {
    /** Draw with the dark palette, as the canvas does in the dark theme. Default false. */
    dark?: boolean;
    /** The item id or name. */
    item: string;
    /** Pixels along the longer side of the picture (16 to 1024). Default 256. */
    max_side?: number | null;
  };
  /** The bytes of an inline export. */
  type O_ExportBytes = {
    /** The content, base64. */
    base64: string;
    /** Its media type. */
    mime: string;
    [key: string]: unknown;
  };
  /** Output of `library.thumbnail`. */
  export type Output = {
    /** The PNG, with a transparent background. */
    bytes: O_ExportBytes;
    /** Always false. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** Height of the picture in pixels. */
    height: number;
    /** The item that was drawn. */
    item: string;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    /** Width of the picture in pixels. */
    width: number;
    [key: string]: unknown;
  };
}

/** Returns the profiler's counters, per-phase histograms, redraw counts with their reasons and frame-time percentiles. */
export namespace PerfStats {
  /** What `perf.stats` reports. */
  type A_Since = "start" | "last_call";
  /** Arguments of `perf.stats`. */
  export type Args = {
    /** `start` (default) or `last_call`. */
    since?: A_Since;
    /** Add a Chrome-trace JSON of the retained spans under `trace`. */
    trace?: boolean;
  };
  export type Output = {
    /** True when the command changed any state. */
    changed?: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Selects every unlocked element, or the members of the editing group, a frame or a group. */
export namespace SelectionAll {
  /** An element reference in arguments: an id, or `"@name"` for the name set with `element.set_name`. */
  type A_Ref = string;
  /** Arguments of `selection.all`. */
  export type Args = {
    /**
     * Select only the children of this frame or the members of this group (id or `@name` of the frame, or a
     * group id).
     */
    within?: A_Ref | null;
  };
  /** The selection after a selection command. */
  export type Output = {
    /** False when the selection was already as requested. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The group whose members are being edited individually. */
    editing_group?: string | null;
    /** Groups selected as a whole. */
    groups: string[];
    /** The selected element ids, back to front (bound text is not listed: it follows its container). */
    selected: string[];
    /** Locked elements that were left out because `include_locked` was false. */
    skipped_locked: string[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Clears the selection and leaves the editing group and the point editor. */
export namespace SelectionClear {
  /** An argument struct with no fields, for commands that take none. */
  export type Args = Record<string, never>;
  /** The selection after a selection command. */
  export type Output = {
    /** False when the selection was already as requested. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The group whose members are being edited individually. */
    editing_group?: string | null;
    /** Groups selected as a whole. */
    groups: string[];
    /** The selected element ids, back to front (bound text is not listed: it follows its container). */
    selected: string[];
    /** Locked elements that were left out because `include_locked` was false. */
    skipped_locked: string[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Returns the selected ids, groups, editing group, common bounds and kinds, or the full fields of each element. */
export namespace SelectionGet {
  /** How much `selection.get` says. */
  type A_Detail = "ids" | "summary" | "full";
  /** Arguments of `selection.get`. */
  export type Args = {
    /** How much to return. */
    detail?: A_Detail;
  };
  /** A rectangle in world units. */
  type O_BoundsOut = {
    /** Height. */
    h: number;
    /** Width. */
    w: number;
    /** Left edge. */
    x: number;
    /** Top edge. */
    y: number;
    [key: string]: unknown;
  };
  /** The point editor of a line or arrow. */
  type O_LinearEditorOut = {
    /** The element. */
    element: string;
    /** Selected point indexes. */
    selected_points: number[];
    [key: string]: unknown;
  };
  /** Result of `selection.get`. */
  export type Output = {
    /** The common bounds of the selected elements (rotation included); null when nothing is selected. */
    bounds?: O_BoundsOut | null;
    /** True when the command changed any state. */
    changed?: boolean;
    /** How many elements are selected. */
    count: number;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The group whose members are being edited individually. */
    editing_group?: string | null;
    /** Every field of every selected element; only with `detail=full`. */
    elements?: unknown[] | null;
    /** Groups selected as a whole. */
    groups?: string[];
    /** The selected element ids, back to front. */
    ids: string[];
    /** How many selected elements there are of each kind. */
    kinds?: {
      [key: string]: number;
    };
    /** The point editor, when a line or arrow is being edited point by point. */
    linear_editor?: O_LinearEditorOut | null;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Selects the element that the selected one is connected to by an arrow, in a direction. */
export namespace SelectionNavigate {
  /** A direction on the canvas. */
  type A_Dir = "up" | "down" | "left" | "right";
  /** Arguments of `selection.navigate`. */
  export type Args = {
    /** Which way to go from the selected element. */
    direction: A_Dir;
  };
  /** The selection after a selection command. */
  export type Output = {
    /** False when the selection was already as requested. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The group whose members are being edited individually. */
    editing_group?: string | null;
    /** Groups selected as a whole. */
    groups: string[];
    /** The selected element ids, back to front (bound text is not listed: it follows its container). */
    selected: string[];
    /** Locked elements that were left out because `include_locked` was false. */
    skipped_locked: string[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Selects elements by id, group or filter and combines them with the selection by replace, add, remove or toggle. */
export namespace SelectionSelect {
  /** #rrggbb, or #rrggbbaa for a non-opaque colour. 'transparent' and #rgb are also accepted. */
  type A_Color = string;
  /** How a filled area is painted. The fill colour itself is `Style::fill_color`; `None` there means no fill. */
  type A_FillPattern = "solid" | "hachure" | "zigzag" | "cross_hatch" | "dots" | "dashed" | "zigzag_line";
  /**
   * Font family. `GelPen`, `GelPenSerif`, `VanillaExtract` and `PlexSans` ship with the app; `NotoSans` is the old
   * fallback.
   */
  type A_FontFamily = "gelpen" | "noto_sans" | "gelpen_serif" | "vanilla_extract" | "plex_sans";
  type A_GroupId = string;
  /** The kind tag without data. */
  type A_Kind = "rectangle" | "diamond" | "ellipse" | "line" | "arrow" | "freehand" | "text" | "math" | "image" | "frame";
  /** Which arrows count as a connection. */
  type A_LinkDirection = "in" | "out" | "any";
  /** How a selection change combines with the current selection. */
  type A_Mode = "replace" | "add" | "remove" | "toggle";
  /** One value or a list of values. */
  type A_OneOrMany = A_Kind | A_Kind[];
  /** A rectangle as `{x, y, w, h}`. */
  type A_RectSpec = {
    /** Height. */
    h: number;
    /** Width. */
    w: number;
    /** Left. */
    x: number;
    /** Top. */
    y: number;
  };
  /** An element reference in arguments: an id, or `"@name"` for the name set with `element.set_name`. */
  type A_Ref = string;
  /** Arrows bound to an element, and the elements on their other end. The element is an id or `@name`. */
  type A_RefConnectedTo = {
    /** The direction of the arrows. */
    direction?: A_LinkDirection;
    /** The element: an id or `@name`. */
    ref: string;
  };
  /** The filter of `element.query` with elements given as ids or `@name`. Every given field must match (AND). */
  type A_RefQuery = {
    /** The label of this container (an id or `@name`). */
    bound_text_of?: string | null;
    /** Connected by arrows to this element. */
    connected_to?: A_RefConnectedTo | null;
    /** Children of this frame (an id or `@name`). */
    frame?: string | null;
    /** Members of this group. */
    group?: A_GroupId | null;
    /** Has a bound label or not. */
    has_label?: boolean | null;
    /** Only these elements (ids or `@name`). */
    ids?: string[] | null;
    /** One kind or a list of kinds. */
    kind?: A_OneOrMany | null;
    /** Locked or not. */
    locked?: boolean | null;
    /** The element name, as a glob (`*` any run, `?` one character). Case-sensitive. */
    name?: string | null;
    /** A region of the canvas. */
    region?: A_RegionFilter | null;
    /** In the selection or not. */
    selected?: boolean | null;
    /** Style values. */
    style?: A_StyleFilter | null;
    /** Text, labels and LaTeX that match. */
    text?: A_TextFilter | null;
  };
  /** Elements in a region of the canvas, by their (rotated) bounding boxes. */
  type A_RegionFilter = {
    /** How the element relates to it. */
    mode?: A_RegionMode;
    /** The region. */
    rect: A_RectSpec;
  };
  /** How an element relates to the region. */
  type A_RegionMode = "overlap" | "contain" | "contained_by";
  /** How hand-drawn the outline looks. The names are the old app's; `roughness` gives the numeric value. */
  type A_Sloppiness = "architect" | "artist" | "cartoonist" | "drunk";
  /** Dash pattern of a stroke. */
  type A_StrokeStyle = "solid" | "dashed" | "dotted";
  /** Exact style values to match. Only the properties that are given are compared. */
  type A_StyleFilter = {
    /** Corner radius. */
    corner_radius?: number | null;
    /** Fill colour. `"transparent"` matches elements without a fill. */
    fill_color?: A_Color | null;
    /** Fill pattern. */
    fill_pattern?: A_FillPattern | null;
    /** Font family (text only). */
    font_family?: A_FontFamily | null;
    /** Font size (text only). */
    font_size?: number | null;
    /** Opacity. */
    opacity?: number | null;
    /** Sloppiness. */
    sloppiness?: A_Sloppiness | null;
    /** Stroke colour. */
    stroke_color?: A_Color | null;
    /** Dash pattern. */
    stroke_style?: A_StrokeStyle | null;
    /** Stroke width. */
    stroke_width?: number | null;
    /** Text alignment (text only). */
    text_align?: A_TextAlign | null;
  };
  /** Horizontal text alignment. */
  type A_TextAlign = "left" | "center" | "right";
  /** Text to look for in the text of elements, their labels and LaTeX. Case-insensitive. */
  type A_TextFilter = string | {
    /** A phrase the text contains. */
    contains?: string | null;
    /** A regular expression: literals, `.`, classes like `[a-z]`, `* + ?`, `^ $`, `|`, and `\d \w \s`. */
    regex?: string | null;
  };
  /** Arguments of `selection.select`. */
  export type Args = {
    /**
     * Select the elements themselves, not their outermost group; the editing group becomes the innermost group
     * they share.
     */
    deep?: boolean;
    /** Select every element that matches this filter (the filter of `element.query`). */
    filter?: A_RefQuery | null;
    /** A group to select (all its members). */
    group?: A_GroupId | null;
    /** Elements to select, by id or `@name`. Give exactly one of `ids`, `group` or `filter`. */
    ids?: A_Ref[] | null;
    /** Also select locked elements. Without it they are skipped and listed in `skipped_locked`. */
    include_locked?: boolean;
    /** How to combine with the current selection. */
    mode?: A_Mode;
  };
  /** The selection after a selection command. */
  export type Output = {
    /** False when the selection was already as requested. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The group whose members are being edited individually. */
    editing_group?: string | null;
    /** Groups selected as a whole. */
    groups: string[];
    /** The selected element ids, back to front (bound text is not listed: it follows its container). */
    selected: string[];
    /** Locked elements that were left out because `include_locked` was false. */
    skipped_locked: string[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

