/** Applies a named style bundle to elements and to the defaults for new elements, and optionally sets the page colour. */
export namespace StyleApplyTheme {
  /** An element reference in arguments: an id, or `"@name"` for the name set with `element.set_name`. */
  type A_Ref = string;
  /** Where `style.set` and `style.apply_theme` write. */
  type A_Scope = "auto" | "selection" | "defaults" | "both";
  /** Arguments of `style.apply_theme`. */
  export type Args = {
    /** The elements to change. Default: the selection. */
    ids?: A_Ref[] | null;
    /** The theme: default, monochrome, pastel, blueprint or high_contrast. See `style.list_themes`. */
    name: string;
    /** Where to write; the same as for `style.set`. */
    scope?: A_Scope;
    /** Also set the page colour to the theme's background. */
    set_background?: boolean;
  };
  /** The properties that were skipped for an element. */
  type O_Skipped = {
    /** The element. */
    id: string;
    /** The properties it does not support. */
    props: string[];
    [key: string]: unknown;
  };
  /** Output of `style.apply_theme`. */
  export type Output = {
    /** The properties each element took, by element id. */
    applied: {
      [key: string]: string[];
    };
    /** True when the page colour changed. */
    background_set: boolean;
    /** False when everything already matched the theme. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** True when the defaults for new elements were part of this call. */
    defaults_updated: boolean;
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The properties an element does not support. */
    skipped: O_Skipped[];
    /** The theme that was applied. */
    theme: string;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Reads style properties of elements or of the defaults: the common value or "mixed", and whether each property applies. */
export namespace StyleGet {
  /** Where `style.get` reads. */
  type A_GetScope = "auto" | "selection" | "defaults";
  /** An element reference in arguments: an id, or `"@name"` for the name set with `element.set_name`. */
  type A_Ref = string;
  /** Arguments of `style.get`. */
  export type Args = {
    /** The elements to read. Default: the selection. */
    ids?: A_Ref[] | null;
    /** The properties to report, by name. Default: all of them. */
    props?: string[] | null;
    /** Read the elements, the defaults, or the elements if there are any and the defaults if not. */
    scope?: A_GetScope;
  };
  /** The kind tag without data. */
  type O_Kind = "rectangle" | "diamond" | "ellipse" | "line" | "arrow" | "freehand" | "text" | "math" | "image" | "frame";
  /** One property over the targets. */
  type O_PropInfo = {
    /** True when at least one target supports the property. */
    applicable: boolean;
    /**
     * Why the property cannot be set now: the text `style.set` refuses with for this property alone. Only when
     * the targets are elements and none of them supports it. A control greys itself with this text.
     */
    reason?: string | null;
    /**
     * The common value, or the word `"mixed"` when the supporting targets differ. Absent when not applicable. A
     * removed fill is `null`.
     */
    value?: unknown;
    [key: string]: unknown;
  };
  /** Output of `style.get`. */
  export type Output = {
    /** Always false: reading changes nothing. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The elements that were read. */
    ids: string[];
    /** The kinds among them, without repeats. */
    kinds: O_Kind[];
    /** The requested properties. */
    props: {
      [key: string]: O_PropInfo;
    };
    /** `selection` (the targets were read) or `defaults`. */
    source: string;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

/** Lists the built-in themes with the style properties and background each one sets. */
export namespace StyleListThemes {
  /** An argument struct with no fields, for commands that take none. */
  export type Args = Record<string, never>;
  /** Brush of a freehand stroke. */
  type O_Brush = "normal" | "calligraphy";
  /** #rrggbb, #rrggbbaa, #rgb, 'transparent', or a palette name '<family>-<shade>' such as 'blue-500' (22 Tailwind families, shades 25, 50, 100-900, 950). */
  type O_ColorArg = string;
  /** How a filled area is painted. The fill colour itself is `Style::fill_color`; `None` there means no fill. */
  type O_FillPattern = "solid" | "hachure" | "zigzag" | "cross_hatch" | "dots" | "dashed" | "zigzag_line";
  /**
   * Font family. `GelPen`, `GelPenSerif`, `VanillaExtract` and `PlexSans` ship with the app; `NotoSans` is the old
   * fallback.
   */
  type O_FontFamily = "gelpen" | "noto_sans" | "gelpen_serif" | "vanilla_extract" | "plex_sans";
  /** Font weight. */
  type O_FontWeight = "light" | "regular" | "heavy";
  /** How pen pressure shapes a freehand stroke. */
  type O_PressureMode = "uniform" | "simulated" | "device";
  /** How hand-drawn the outline looks. The names are the old app's; `roughness` gives the numeric value. */
  type O_Sloppiness = "architect" | "artist" | "cartoonist" | "drunk";
  /** Dash pattern of a stroke. */
  type O_StrokeStyle = "solid" | "dashed" | "dotted";
  /** A set of style properties to change. Absent properties stay as they are. */
  type O_StyleProps = {
    /** Corner radius in world units, 0 or more (0 is sharp). */
    corner_radius?: number | null;
    /** Fill colour. `null` removes the fill. */
    fill_color?: O_ColorArg | null;
    /** How the fill is painted: solid, hachure, zigzag, cross_hatch, dots, dashed or zigzag_line. */
    fill_pattern?: O_FillPattern | null;
    /** Font: gelpen, gelpen_serif, vanilla_extract, noto_sans or plex_sans. */
    font_family?: O_FontFamily | null;
    /** Font size in world units, above 0 (presets 16, 20, 28, 36). */
    font_size?: number | null;
    /** Font weight: light, regular or heavy. */
    font_weight?: O_FontWeight | null;
    /** Freehand brush: normal or calligraphy. */
    freehand_style?: O_Brush | null;
    /** Line height as a multiple of the font size, 1.0 to 3.0 (default 1.25). */
    line_height?: number | null;
    /** Opacity from 0 (invisible) to 1. */
    opacity?: number | null;
    /** Freehand pressure: uniform, simulated or device. */
    pressure_mode?: O_PressureMode | null;
    /** How hand-drawn the outline is: architect, artist, cartoonist or drunk. */
    sloppiness?: O_Sloppiness | null;
    /** Outline colour; the text colour of text and math. */
    stroke_color?: O_ColorArg | null;
    /** solid, dashed or dotted. */
    stroke_style?: O_StrokeStyle | null;
    /** Outline width in world units, above 0 (presets 1, 2, 4, 8). */
    stroke_width?: number | null;
    /** Horizontal text alignment: left, center or right. */
    text_align?: O_TextAlign | null;
    /** Vertical alignment of text bound to a container: top, middle or bottom. */
    vertical_align?: O_VerticalAlign | null;
  };
  /** Horizontal text alignment. */
  type O_TextAlign = "left" | "center" | "right";
  /** A named style bundle and an optional page colour. */
  type O_Theme = {
    /** The page colour, applied only when asked. */
    background?: O_ColorArg | null;
    /** The name `style.apply_theme` takes. */
    name: string;
    /** The properties it sets. */
    props: O_StyleProps;
    [key: string]: unknown;
  };
  /** Vertical alignment of text inside its box or container. */
  type O_VerticalAlign = "top" | "middle" | "bottom";
  /** Output of `style.list_themes`. */
  export type Output = {
    /** Always false: reading changes nothing. */
    changed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** Ids of elements the command removed. */
    deleted?: string[];
    /** The built-in themes with their bundles. */
    themes: O_Theme[];
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

