/** Ends the text edit session: applies the editor's final content in one undo step, or discards it. */
export namespace TextEditEnd {
  /** Brush of a freehand stroke. */
  type A_Brush = "normal" | "calligraphy";
  /** #rrggbb, or #rrggbbaa for a non-opaque colour. 'transparent' and #rgb are also accepted. */
  type A_Color = string;
  /** #rrggbb, #rrggbbaa, #rgb, 'transparent', or a palette name '<family>-<shade>' such as 'blue-500' (22 Tailwind families, shades 25, 50, 100-900, 950). */
  type A_ColorArg = string;
  /** How a filled area is painted. The fill colour itself is `Style::fill_color`; `None` there means no fill. */
  type A_FillPattern = "solid" | "hachure" | "zigzag" | "cross_hatch" | "dots" | "dashed" | "zigzag_line";
  /**
   * Font family. `GelPen`, `GelPenSerif`, `VanillaExtract` and `PlexSans` ship with the app; `NotoSans` is the old
   * fallback.
   */
  type A_FontFamily = "gelpen" | "noto_sans" | "gelpen_serif" | "vanilla_extract" | "plex_sans";
  /** Font weight. */
  type A_FontWeight = "light" | "regular" | "heavy";
  /**
   * Whether `$...$` in a text is typeset as inline math.
   *
   * The text stays plain: the dollar signs are part of `content`, and so is the escape `\$`. This setting only says how
   * the text is drawn and measured (`docs/model.md` section 4, "Inline math").
   */
  type A_InlineMath = "auto" | "off";
  /** How pen pressure shapes a freehand stroke. */
  type A_PressureMode = "uniform" | "simulated" | "device";
  /** One style range chosen in the editor: a colour, bold, italic. */
  type A_RunArg = {
    /** The range is bold. */
    bold?: boolean;
    /** The colour of the range: `#rrggbb`, `#rrggbbaa` or `transparent`. Absent: the element's colour. */
    color?: A_Color | null;
    /** One past the last character. */
    end: number;
    /** The range is italic. */
    italic?: boolean;
    /** First character. */
    start: number;
  };
  /** How hand-drawn the outline looks. The names are the old app's; `roughness` gives the numeric value. */
  type A_Sloppiness = "architect" | "artist" | "cartoonist" | "drunk";
  /** Dash pattern of a stroke. */
  type A_StrokeStyle = "solid" | "dashed" | "dotted";
  /** A set of style properties to change. Absent properties stay as they are. */
  type A_StyleProps = {
    /** Corner radius in world units, 0 or more (0 is sharp). */
    corner_radius?: number | null;
    /** Fill colour. `null` removes the fill. */
    fill_color?: A_ColorArg | null;
    /** How the fill is painted: solid, hachure, zigzag, cross_hatch, dots, dashed or zigzag_line. */
    fill_pattern?: A_FillPattern | null;
    /** Font: gelpen, gelpen_serif, vanilla_extract, noto_sans or plex_sans. */
    font_family?: A_FontFamily | null;
    /** Font size in world units, above 0 (presets 16, 20, 28, 36). */
    font_size?: number | null;
    /** Font weight: light, regular or heavy. */
    font_weight?: A_FontWeight | null;
    /** Freehand brush: normal or calligraphy. */
    freehand_style?: A_Brush | null;
    /** Line height as a multiple of the font size, 1.0 to 3.0 (default 1.25). */
    line_height?: number | null;
    /** Opacity from 0 (invisible) to 1. */
    opacity?: number | null;
    /** Freehand pressure: uniform, simulated or device. */
    pressure_mode?: A_PressureMode | null;
    /** How hand-drawn the outline is: architect, artist, cartoonist or drunk. */
    sloppiness?: A_Sloppiness | null;
    /** Outline colour; the text colour of text and math. */
    stroke_color?: A_ColorArg | null;
    /** solid, dashed or dotted. */
    stroke_style?: A_StrokeStyle | null;
    /** Outline width in world units, above 0 (presets 1, 2, 4, 8). */
    stroke_width?: number | null;
    /** Horizontal text alignment: left, center or right. */
    text_align?: A_TextAlign | null;
    /** Vertical alignment of text bound to a container: top, middle or bottom. */
    vertical_align?: A_VerticalAlign | null;
  };
  /** Horizontal text alignment. */
  type A_TextAlign = "left" | "center" | "right";
  /** Vertical alignment of text inside its box or container. */
  type A_VerticalAlign = "top" | "middle" | "bottom";
  /** Arguments of `text.edit_end`. */
  export type Args = {
    /** True: apply the editor's content. False: discard the session and leave the document as it was. */
    commit?: boolean;
    /** Whether `$...$` in the text is typeset as math (`auto` or `off`, see `text.set`). Absent keeps the setting. */
    inline_math?: A_InlineMath | null;
    /** The final formula, when a math element is edited. */
    latex?: string | null;
    /** Style ranges of the text (colour, bold, italic). Absent keeps the current ones. */
    runs?: A_RunArg[] | null;
    /**
     * Text properties chosen during the edit, applied in the same step: the colour, opacity and font
     * properties of `style.set` (`stroke_color`, `opacity`, `font_family`, `font_weight`, `font_size`,
     * `text_align`, `vertical_align`, `line_height`). Other style properties are refused.
     */
    style?: A_StyleProps | null;
    /** The final content of the text or label. Absent keeps the current content (and discards a draft). */
    text?: string | null;
  };
  /** Output of `text.edit_end`. */
  export type Output = {
    /** True when the command changed any state. */
    changed?: boolean;
    /** True when the editor's result was applied (even if it changed nothing). */
    committed: boolean;
    /** Ids of elements the command made. */
    created?: string[];
    /** The text element or label was deleted. */
    deleted: boolean;
    /** A blank result discarded a draft, or deleted the text or label. */
    discarded: boolean;
    /** The element that was created or edited. For a label: the label text. Absent when nothing is left. */
    id?: string | null;
    /** The element is selected now (the container, for a label). */
    selected?: string | null;
    /** The label of the undo step the command pushed. */
    undo_label?: string;
    /** Non-fatal notes. */
    warnings?: string[];
    [key: string]: unknown;
  };
}

